/* Plant icons for the planner: the same painted sprites, as image URLs. */
let painter=null;const urls=new Map();
export function spriteURL(key){
  if(urls.has(key))return urls.get(key);
  let url='';
  try{painter=painter||createScene(document.createElement('canvas'),{spritesOnly:true});url=painter.sprite(key,0).toDataURL('image/png')}catch(e){url=''}
  urls.set(key,url);return url;
}
